import{_ as t,o,c as a,a2 as d}from"./chunks/framework.Ch4PdLd_.js";const u=JSON.parse('{"title":"nekcode 如何工作","description":"","frontmatter":{},"headers":[],"relativePath":"start/how-it-works.md","filePath":"start/how-it-works.md"}'),n={name:"start/how-it-works.md"};function s(r,e,c,l,i,p){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="nekcode-如何工作" tabindex="-1">nekcode 如何工作 <a class="header-anchor" href="#nekcode-如何工作" aria-label="Permalink to &quot;nekcode 如何工作&quot;">​</a></h1><p>这一页解释 nek 内部的几个核心概念：代理循环（agent loop）、上下文、会话树、模式和工具。理解它们以后，排队消息、分支、压缩、Plan 模式这些功能的行为就都说得通了。</p><h2 id="agent-loop" tabindex="-1">代理循环 <a class="header-anchor" href="#agent-loop" aria-label="Permalink to &quot;代理循环 {#agent-loop}&quot;">​</a></h2><p>你发送一条消息后，nek 做的事情是一个循环：</p><ol><li>把你的消息追加到当前分支；</li><li>用系统提示词、当前分支的历史、可用工具和模型设置拼出一次模型请求，发给所选服务商；</li><li>服务商流式返回助手回复，回复里可以有文字，也可以有<strong>工具调用</strong>；</li><li>nek 记录回复，执行每个工具调用（同一条回复里的多个调用可以并行），记录结果；</li><li>如果有工具结果或排队消息需要模型继续处理，回到第 2 步开始下一<strong>轮（turn）</strong>；否则这次**运行（run）**结束。</li></ol><p>一轮 = 一次助手回复 + 它触发的工具调用和结果。一次运行可以包含很多轮。</p><p>运行过程中你可以继续输入：</p><table tabindex="0"><thead><tr><th>消息类型</th><th>何时送达</th><th>默认按键</th></tr></thead><tbody><tr><td>插话（steering）</td><td>当前这一轮的工具执行完之后、下一次模型请求之前</td><td><code>Enter</code></td></tr><tr><td>追加（follow-up）</td><td>整个运行结束、没有其他待办工作之后</td><td><code>Alt+Enter</code>（Windows/WSL 为 <code>Ctrl+Q</code>）</td></tr></tbody></table><p>按 <code>Escape</code> 中止当前运行，排队中的消息会退回输入框。</p><h3 id="自动重试" tabindex="-1">自动重试 <a class="header-anchor" href="#自动重试" aria-label="Permalink to &quot;自动重试&quot;">​</a></h3><p>服务商返回过载、限流、5xx、连接中断这类临时错误时，nek 会按 <code>retry</code> 设置指数退避自动重试（默认最多 3 次），见 <a href="/nekcode/reference/settings#network">settings.json</a>。</p><h2 id="context" tabindex="-1">上下文 <a class="header-anchor" href="#context" aria-label="Permalink to &quot;上下文 {#context}&quot;">​</a></h2><p>模型每次看到的内容由这些部分组成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌ 系统提示词 ───────────────────────────────┐</span></span>
<span class="line"><span>│ nek 的身份句 + 基础指令 + 各工具的使用说明    │</span></span>
<span class="line"><span>│ + Skills 列表（只有名字和描述）               │</span></span>
<span class="line"><span>│ + APPEND_SYSTEM.md 等追加内容                │</span></span>
<span class="line"><span>├ 项目指令 ─────────────────────────────────┤</span></span>
<span class="line"><span>│ AGENTS.md / CLAUDE.md（每次请求都会带上）     │</span></span>
<span class="line"><span>├ 当前分支的历史 ────────────────────────────┤</span></span>
<span class="line"><span>│ [压缩摘要] + 用户消息 + 助手回复 + 工具结果 ... │</span></span>
<span class="line"><span>└──────────────────────────────────────────┘</span></span>
<span class="line"><span>+ 工具声明（名字、描述、参数 schema）</span></span></code></pre></div><p>几点说明：</p><ul><li><strong>项目指令</strong>（<code>AGENTS.md</code>）不放在系统提示词里，而是每次请求时在系统消息之后插入一条单独的消息，不写入对话记录。这样在一个会话里，系统提示词和工具声明保持稳定，服务商的提示词缓存不会因为指令变化而整段失效。</li><li><strong>Skills</strong> 只把名字、描述和路径放进系统提示词；模型判断需要时才读取完整的 <code>SKILL.md</code>。</li><li><strong>提示词模板</strong> 在你的输入变成用户消息之前就展开了。</li><li>你用 <code>@</code> 引用的文件、粘贴的图片、<code>!</code> 命令的输出，都会成为消息内容。</li><li>扩展可以追加指令，或者在发送前改写上下文。</li></ul><p>上下文接近模型上限时，nek 会自动<strong>压缩</strong>：把较早的历史总结成一段摘要，保留最近的消息。原始记录仍然保存在会话里。见 <a href="/nekcode/guide/sessions#compaction">会话与上下文</a> 和 <a href="/nekcode/reference/compaction">上下文压缩</a>。</p><h2 id="sessions" tabindex="-1">会话与分支 <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;会话与分支 {#sessions}&quot;">​</a></h2><p>会话里的每条消息和事件都是一个<strong>条目（entry）</strong>，每个条目有 ID，并指向它的父条目，所以整个会话是一棵<strong>树</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户 ─ 助手 ─ 用户 ─ 助手 ─┬─ 用户 ─ 助手        ← 当前分支（活动分支）</span></span>
<span class="line"><span>                          └─ 分支摘要 ─ 用户     ← 另一个分支</span></span></code></pre></div><ul><li>从树根到当前条目的那条路径叫<strong>活动分支</strong>，它就是下一次请求的历史。</li><li>用 <code>/tree</code> 回到较早的某一点继续，会在同一个会话里长出新分支，原来的分支不会丢。</li><li><code>/fork</code> 和 <code>/clone</code> 把选定的历史复制到一个新会话。</li></ul><p>持久化的会话是 SQLite 数据库，由 durable 引擎写入：一轮里的每一步（你的输入、流式文本、每个工具调用和结果、排队消息、压缩）都先落盘再继续。所以进程被杀之后重开会话，中断的那一轮会接着跑。见 <a href="/nekcode/reference/durable-sessions">Durable 会话与崩溃续跑</a>。</p><h2 id="modes" tabindex="-1">模式 <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;模式 {#modes}&quot;">​</a></h2><p>nek 有两种工作模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>能做什么</th><th>进入方式</th></tr></thead><tbody><tr><td>Agent（默认）</td><td>读写文件、执行命令，正常完成任务</td><td>默认；<code>/agent</code>；<code>Alt+M</code></td></tr><tr><td>Plan</td><td>只调研和写计划；<code>edit</code>/<code>write</code> 只能改 Markdown 文件，子代理只读</td><td><code>/plan</code>；<code>Alt+M</code>；<code>nek --plan</code></td></tr></tbody></table><p>Plan 模式写完计划后由你审阅，批准后切换到 Agent 模式实施。模型自己也可以通过 <code>switch_mode</code> 工具<strong>提议</strong>切换，但必须由你确认。见 <a href="/nekcode/guide/plan-mode">Plan 模式</a>。</p><h2 id="tools" tabindex="-1">工具 <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;工具 {#tools}&quot;">​</a></h2><p>模型通过工具与外部世界交互。nek 的工具分几类：</p><table tabindex="0"><thead><tr><th>类别</th><th>工具</th></tr></thead><tbody><tr><td>文件</td><td><code>read</code>、<code>edit</code>、<code>write</code></td></tr><tr><td>搜索</td><td><code>grep</code>、<code>find</code>、<code>ls</code>、<code>ast_grep</code>、<code>web_search</code></td></tr><tr><td>命令</td><td><code>bash</code>（Windows 可选 <code>powershell</code>）</td></tr><tr><td>规划与协作</td><td><code>todo_write</code>、<code>switch_mode</code>、<code>create_plan</code>、<code>update_plan</code>、<code>ask_question</code></td></tr><tr><td>子代理</td><td><code>subagent</code>、<code>await</code></td></tr><tr><td>按需加载</td><td><code>tool_search</code>（存在延迟加载的工具时才出现，例如 MCP 工具）</td></tr></tbody></table><p>每个工具的行为见 <a href="/nekcode/guide/tools">内置工具</a>。工具以 nek 进程的操作系统权限运行，nek 不提供沙箱。</p><h2 id="interfaces" tabindex="-1">界面与运行方式 <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;界面与运行方式 {#interfaces}&quot;">​</a></h2><p>同一套代理和会话机制有多种使用方式：</p><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td>交互模式</td><td>默认的终端界面</td></tr><tr><td>print 模式</td><td><code>nek -p &quot;...&quot;</code>，执行一次，把最终回复打印到 stdout</td></tr><tr><td>JSON 模式</td><td><code>nek --mode json &quot;...&quot;</code>，把事件流以 JSONL 写到 stdout</td></tr><tr><td>RPC 模式</td><td><code>nek --mode rpc</code>，从 stdin 接收 JSONL 命令，长期运行</td></tr><tr><td>SDK</td><td>在 Node.js/Bun 程序里直接创建和控制会话</td></tr></tbody></table><p>见 <a href="/nekcode/develop/cli-integration">脚本与程序集成</a>。</p><h2 id="extensions" tabindex="-1">内置扩展与资源 <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;内置扩展与资源 {#extensions}&quot;">​</a></h2><p>nek 的独有功能（Plan、Todo、子代理、提问框）以一个名为 <code>nek</code> 的内置扩展实现；MCP、<code>tool_search</code>、llama.cpp 服务商也是内置扩展。你自己的扩展可以注册工具、命令、快捷键、服务商、事件处理和界面组件，见 <a href="/nekcode/develop/extensions">编写扩展</a>。</p><p>其他资源：</p><ul><li><strong>Skills</strong>：按需加载的专项说明和配套文件；</li><li><strong>提示词模板</strong>：可复用的消息文本，作为 <code>/</code> 命令使用；</li><li><strong>主题</strong>：终端配色。</li></ul><h2 id="trust" tabindex="-1">信任与权限 <a class="header-anchor" href="#trust" aria-label="Permalink to &quot;信任与权限 {#trust}&quot;">​</a></h2><p>nek 在加载项目配置和资源之前先决定是否<strong>信任</strong>这个项目。信任只决定加载哪些项目资源，<strong>不是沙箱</strong>：启用的工具始终以 nek 进程的权限运行，扩展也在 nek 进程内执行。处理不可信的代码请使用容器或其他沙箱，见 <a href="/nekcode/guide/security">安全使用</a>。</p>`,40)])])}const k=t(n,[["render",s]]);export{u as __pageData,k as default};
